#[test]
fn live_tmux_tests_are_not_in_default_development_suite() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let sources = [
        "src/autoclaim.rs",
        "agent-doc-focus-io/src/lib.rs",
        "agent-doc-sync-io/src/resync.rs",
        "agent-doc-orchestration/src/route.rs",
        "src/session_actor_cmd.rs",
        "agent-doc-session-registry-io/src/registration.rs",
        "agent-doc-orchestration/src/start.rs",
        "agent-doc-sync-io/src/sync.rs",
    ];
    let mut unignored = Vec::new();

    for source in sources {
        let path = manifest_dir.join(source);
        let content = fs::read_to_string(&path).unwrap();
        for block in content.split("#[test]").skip(1) {
            let Some(fn_pos) = block.find("fn ") else {
                continue;
            };
            let fn_block = &block[fn_pos..];
            let Some(open_brace) = fn_block.find('{') else {
                continue;
            };
            let mut depth = 0usize;
            let mut end = fn_block.len();
            for (index, ch) in fn_block[open_brace..].char_indices() {
                match ch {
                    '{' => depth += 1,
                    '}' => {
                        depth = depth.saturating_sub(1);
                        if depth == 0 {
                            end = open_brace + index + ch.len_utf8();
                            break;
                        }
                    }
                    _ => {}
                }
            }
            let header_and_body = &block[..fn_pos + end];
            if !header_and_body.contains("IsolatedTmux::new") {
                continue;
            }
            if !header_and_body.contains("#[ignore") {
                let name = header_and_body
                    .split("fn ")
                    .nth(1)
                    .and_then(|rest| rest.split('(').next())
                    .unwrap_or("<unknown>");
                unignored.push(format!("{source}::{name}"));
            }
        }
    }

    assert!(
        unignored.is_empty(),
        "live tmux tests must be #[ignore] and run through `make tmux-ci`: {unignored:?}"
    );
}

