#[test]
fn test_cli_audit_docs_treats_mtime_staleness_as_advisory() {
    let tmp = tempfile::TempDir::new().unwrap();
    let root = tmp.path();

    std::fs::write(root.join("Cargo.toml"), "[package]\nname = \"test\"\n").unwrap();
    std::fs::write(
        root.join("AGENTS.md"),
        "# Agent Instructions\n\nUse `cargo test` before changing code.\n",
    )
    .unwrap();
    std::fs::create_dir_all(root.join("src")).unwrap();
    std::fs::write(root.join("src/main.rs"), "fn main() {}\n").unwrap();

    let old_time = filetime::FileTime::from_unix_time(1_700_000_000, 0);
    let new_time = filetime::FileTime::from_unix_time(1_700_000_100, 0);
    filetime::set_file_mtime(root.join("AGENTS.md"), old_time).unwrap();
    filetime::set_file_mtime(root.join("src/main.rs"), new_time).unwrap();

    let mut cmd = agent_doc_cmd();
    cmd.current_dir(root);
    cmd.arg("audit-docs");
    cmd.assert()
        .success()
        .stdout(predicate::str::contains("Mtime advisory"))
        .stdout(predicate::str::contains("No blocking issues found"));
}

#[test]
fn test_cli_ops_summary_groups_ops_log_events() {
    let tmp = tempfile::TempDir::new().unwrap();
    let root = tmp.path();
    fs::create_dir_all(root.join(".agent-doc/logs")).unwrap();
    fs::write(
        root.join(".agent-doc/logs/ops.log"),
        format!(
            "\
[100] ipc_write_consumed file={} patches=1
[101] commit_success file={}
[102] route_dispatch_only_sent file=tasks/b.md pane=%2 harness=opencode proof=accepted proof_scope=accepted_only
[103] route_dispatch_only_submit_unproven file=tasks/b.md pane=%2 harness=opencode delivery=direct_pane_submit submit_mode=tmux_literal_kitty_return proof=accepted proof_scope=accepted_only timeout_secs=10
[104] sync_latency phase=prune_stash_panes elapsed_ms=309 budget_ms=250 status=over_budget mode=full
[105] flow_event file=tasks/b.md flow=document_mutation stage=pre_write_guard outcome=blocked reason=visible_write_typing_defer_active_typing:socket_ipc
",
            root.join("tasks/a.md").display(),
            root.join("tasks/a.md").display()
        ),
    )
    .unwrap();

    let mut cmd = agent_doc_cmd();
    cmd.args([
        "ops",
        "summary",
        "--project-root",
        root.to_str().unwrap(),
        "--limit",
        "0",
    ]);
    cmd.assert()
        .success()
        .stdout(predicate::str::contains("write ipc consumed"))
        .stdout(predicate::str::contains("tasks/a.md"))
        .stdout(predicate::str::contains("accepted-only route proof"))
        .stdout(predicate::str::contains("dispatch-only not proven"))
        .stdout(predicate::str::contains(
            "flow document mutation pre-write guard blocked",
        ))
        .stdout(predicate::str::contains("sync over budget"));
}

#[test]
fn test_cli_ops_diagnose_gathers_cycle_artifacts() {
    let tmp = tempfile::TempDir::new().unwrap();
    let root = tmp.path();
    fs::create_dir_all(root.join(".agent-doc/logs")).unwrap();
    fs::create_dir_all(root.join(".agent-doc/captures/doc")).unwrap();
    fs::create_dir_all(root.join(".agent-doc/codex-hooks/sessions")).unwrap();
    fs::create_dir_all(root.join(".agent-doc/hooks/post_write")).unwrap();
    fs::create_dir_all(root.join(".agent-doc/patches")).unwrap();
    fs::create_dir_all(root.join(".agent-doc/state/startup-miss")).unwrap();

    fs::write(
        root.join(".agent-doc/logs/ops.log"),
        "[100] flow_event file=tasks/a.md flow=closeout stage=commit outcome=blocked cycle_id=cycle-a patch_id=patch-a\n",
    )
    .unwrap();
    fs::write(
        root.join(".agent-doc/logs/cycles.jsonl"),
        "{\"op\":\"commit\",\"file\":\"tasks/a.md\",\"cycle_id\":\"cycle-a\"}\n",
    )
    .unwrap();
    fs::write(
        root.join(".agent-doc/logs/session-1.log"),
        "[101] codex_start cycle_id=cycle-a patch_id=patch-a\n",
    )
    .unwrap();
    fs::write(
        root.join(".agent-doc/captures/doc/cycle-a.json"),
        r#"{"cycle_id":"cycle-a","capture_id":"cycle-a","state":"captured","response_body":"secret body"}"#,
    )
    .unwrap();
    fs::write(
        root.join(".agent-doc/codex-hooks/sessions/thread.json"),
        r#"{"thread_id":"thread-1","cycle_id":"cycle-a"}"#,
    )
    .unwrap();
    fs::write(
        root.join(".agent-doc/hooks/post_write/patch-a.json"),
        r#"{"patch_id":"patch-a","cycle_id":"cycle-a","payload":"large plugin payload"}"#,
    )
    .unwrap();
    fs::write(
        root.join(".agent-doc/patches/patch-a.md"),
        "patch_id=patch-a cycle_id=cycle-a\n",
    )
    .unwrap();
    fs::write(
        root.join(".agent-doc/session-actors.json"),
        r#"{"documents":[{"session_id":"session-1","cycle_id":"cycle-a"}]}"#,
    )
    .unwrap();
    fs::write(
        root.join(".agent-doc/state/startup-miss/cycle-a.json"),
        r#"{"cycle_baseline_id":"cycle-a","session_id":"session-1"}"#,
    )
    .unwrap();

    let mut cmd = agent_doc_cmd();
    cmd.args([
        "ops",
        "diagnose",
        "--project-root",
        root.to_str().unwrap(),
        "--cycle-id",
        "cycle-a",
        "--patch-id",
        "patch-a",
        "--session-id",
        "session-1",
        "--limit",
        "0",
        "--json",
    ]);
    let output = cmd.assert().success().get_output().stdout.clone();
    let stdout = String::from_utf8(output).unwrap();

    assert!(stdout.contains("\"ops log\""), "{stdout}");
    assert!(stdout.contains("\"captures\""), "{stdout}");
    assert!(stdout.contains("\"codex hook sessions\""), "{stdout}");
    assert!(stdout.contains("patch-a.md"), "{stdout}");
    assert!(
        stdout.contains("<13 bytes omitted from diagnosis summary>"),
        "large JSON fields should be summarized instead of dumped:\n{stdout}"
    );
}

#[test]
fn test_cli_audit_docs_finds_claude_md() {
    let tmp = tempfile::TempDir::new().unwrap();
    let root = tmp.path();

    std::fs::write(root.join("Cargo.toml"), "[package]\nname = \"test\"\n").unwrap();
    std::fs::write(root.join("CLAUDE.md"), "# Doc\n\nUse serde.\n").unwrap();

    let mut cmd = agent_doc_cmd();
    cmd.current_dir(root);
    cmd.arg("audit-docs");
    let output = cmd.output().unwrap();
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("CLAUDE.md"));
}

#[test]
fn test_cli_audit_docs_reports_missing_tree_path() {
    let tmp = tempfile::TempDir::new().unwrap();
    let root = tmp.path();

    std::fs::write(root.join("Cargo.toml"), "[package]\nname = \"test\"\n").unwrap();
    std::fs::write(
        root.join("CLAUDE.md"),
        "# Doc\n\n## Project Structure\n\n```\nsrc/\n  missing.rs\n```\n",
    )
    .unwrap();

    let mut cmd = agent_doc_cmd();
    cmd.current_dir(root);
    cmd.arg("audit-docs");
    cmd.assert()
        .failure()
        .stdout(predicate::str::contains("Referenced path does not exist"));
}

#[test]
fn test_manifest_uses_publishable_dependency_contract() {
    let manifest_path = Path::new(env!("CARGO_MANIFEST_DIR")).join("Cargo.toml");
    let manifest = fs::read_to_string(manifest_path).unwrap();
    let parsed: toml::Value = toml::from_str(&manifest).unwrap();
    let package_version = parsed["package"]["version"].as_str();
    let dependencies = parsed["dependencies"].as_table().unwrap();
    let agent_kit = dependencies["agent-kit"].as_table().unwrap();

    assert_eq!(
        agent_kit.get("path").and_then(toml::Value::as_str),
        None,
        "published manifests must not depend on a sibling-only agent-kit path"
    );
    assert_eq!(
        agent_kit.get("version").and_then(toml::Value::as_str),
        Some("0.4.1")
    );

    for crate_name in [
        "agent-doc-config",
        "agent-doc-controller-io",
        "agent-doc-codex-hook-io",
        "agent-doc-debounce",
        "agent-doc-diff",
        "agent-doc-diff-io",
        "agent-doc-document-realtime",
        "agent-doc-markdown-ast",
        "agent-doc-ffi",
        "agent-doc-flow",
        "agent-doc-frontmatter",
        "agent-doc-frontmatter-io",
        "agent-doc-fs",
        "agent-doc-hooks-io",
        "agent-doc-ipc-io",
        "agent-doc-ipc-forensics-io",
        "agent-doc-lint-io",
        "agent-doc-memory-io",
        "agent-doc-merge",
        "agent-doc-model-tier",
        "agent-doc-op-capture-io",
        "agent-doc-ops-log-io",
        "agent-doc-owner-pane-io",
        "agent-doc-orchestration",
        "agent-doc-plugin-owner",
        "agent-doc-project-config-io",
        "agent-doc-prompt-context-io",
        "agent-doc-prompt-contract",
        "agent-doc-queue",
        "agent-doc-response-replay-io",
        "agent-doc-response-toc-io",
        "agent-doc-state-backbone",
        "agent-doc-state-wire",
        "agent-doc-status-io",
        "agent-doc-template",
        "agent-doc-template-io",
        "agent-doc-turn",
        "agent-doc-session-accretion-io",
        "agent-doc-turn-scope-io",
        "agent-doc-workflow",
        "agent-doc-workflow-io",
        "agent-doc-work-graph",
    ] {
        let dependency = dependencies[crate_name].as_table().unwrap();
        assert!(
            dependency
                .get("path")
                .and_then(toml::Value::as_str)
                .is_some(),
            "{crate_name} should keep a local path for workspace builds"
        );
        assert_eq!(
            dependency.get("version").and_then(toml::Value::as_str),
            package_version,
            "{crate_name} must also carry a registry version for cargo publish"
        );
    }

    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let members = parsed["workspace"]["members"].as_array().unwrap();
    assert!(
        !members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-core")),
        "agent-doc-core must not be retained as an empty facade workspace crate"
    );
    assert!(
        !manifest_dir.join("agent-doc-core/Cargo.toml").exists(),
        "agent-doc-core manifest should be deleted once focused crates own the API"
    );

    for manifest in
        std::iter::once(manifest_dir.join("Cargo.toml")).chain(members.iter().map(|member| {
            manifest_dir
                .join(member.as_str().unwrap())
                .join("Cargo.toml")
        }))
    {
        let manifest_content = fs::read_to_string(&manifest).unwrap();
        let parsed_manifest: toml::Value = toml::from_str(&manifest_content).unwrap();
        let dependencies = parsed_manifest
            .get("dependencies")
            .and_then(toml::Value::as_table);
        assert!(
            dependencies.is_none_or(|dependencies| !dependencies.contains_key("agent-doc-core")),
            "{} must not depend on deleted agent-doc-core",
            manifest.display()
        );
    }

    let tmux_router = dependencies["tmux-router"].as_table().unwrap();
    assert_eq!(
        tmux_router.get("path").and_then(toml::Value::as_str),
        Some("../tmux-router")
    );
    assert_eq!(
        tmux_router.get("version").and_then(toml::Value::as_str),
        Some("0.3.13")
    );
}

#[test]
fn test_agent_doc_hooks_io_owns_hook_dispatch_adapters() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let workspace_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    let workspace: toml::Value = toml::from_str(&workspace_manifest).unwrap();
    let package_version = workspace["package"]["version"].as_str();
    let members = workspace["workspace"]["members"].as_array().unwrap();
    assert!(
        members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-hooks-io")),
        "agent-doc-hooks-io must stay a first-class workspace crate"
    );

    for relative_manifest in ["Cargo.toml", "agent-doc-orchestration/Cargo.toml"] {
        let manifest = fs::read_to_string(manifest_dir.join(relative_manifest)).unwrap();
        let parsed: toml::Value = toml::from_str(&manifest).unwrap();
        let dependencies = parsed["dependencies"].as_table().unwrap();
        let dependency = dependencies["agent-doc-hooks-io"].as_table().unwrap();
        assert_eq!(
            dependency.get("version").and_then(toml::Value::as_str),
            package_version,
            "{relative_manifest} should depend on the versioned hook IO crate"
        );
    }

    let hooks_io_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-hooks-io/Cargo.toml")).unwrap();
    let parsed: toml::Value = toml::from_str(&hooks_io_manifest).unwrap();
    let dependencies = parsed["dependencies"].as_table().unwrap();
    for required in [
        "agent-doc-capture-io",
        "agent-doc-frontmatter",
        "agent-doc-lease-io",
        "agent-doc-memory-io",
        "agent-doc-model-tier",
        "agent-doc-plugin-owner-io",
        "agent-kit",
    ] {
        assert!(
            dependencies.contains_key(required),
            "agent-doc-hooks-io should depend on hook/frontmatter/model focused crate: {required}"
        );
    }
    for forbidden in [
        "agent-doc-core",
        "agent-doc-orchestration",
        "git2",
        "interprocess",
        "notify",
        "rusqlite",
        "tmux-router",
    ] {
        assert!(
            !dependencies.contains_key(forbidden),
            "agent-doc-hooks-io must stay free of orchestration/editor IPC/sqlite/tmux facades: {forbidden}"
        );
    }

    let hooks_io = fs::read_to_string(manifest_dir.join("agent-doc-hooks-io/src/lib.rs")).unwrap();
    for required in [
        "pub fn fire_doc_hooks(",
        "pub fn fire_doc_event(",
        "pub fn fire_post_write(",
        "pub fn fire_post_commit(",
        "pub fn fire_post_write_with_effects(",
        "pub fn fire_post_commit_with_effects(",
        "pub fn fire_claim(",
        "pub fn fire_layout_change(",
        "pub fn poll(",
        "pub trait PostResponseHookEffects",
        "pub struct PostResponseCapture",
        "pub struct StaleConsumerReapCounts",
        "agent_kit::hooks::{Event, HookRegistry}",
        "std::process::Command::new(\"sh\")",
        "agent_doc_frontmatter::frontmatter::parse",
        "agent_doc_model_tier::canonical_model_name",
        "fn capture_event_metadata(",
    ] {
        assert!(
            hooks_io.contains(required),
            "agent-doc-hooks-io must own hook dispatch adapter: {required}"
        );
    }

    assert!(
        !manifest_dir
            .join("agent-doc-orchestration/src/hooks.rs")
            .exists(),
        "orchestration hooks facade should be deleted once hook IO owns post-response adapters"
    );
    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    assert!(
        !orchestration_lib.contains("pub mod hooks;"),
        "orchestration must not expose a public hooks facade"
    );

    assert!(
        !manifest_dir
            .join("agent-doc-orchestration/src/hook_effects.rs")
            .exists(),
        "orchestration must not keep a hook_effects facade module"
    );
    for required in [
        "pub struct PostResponseHookEffectFns",
        "pub fn post_response_hook_effects",
        "pub fn default_post_response_hook_effects",
        "impl<Load, Memory, Lease, Stale> PostResponseHookEffects",
        "agent_doc_capture_io::load_active(file)",
        "agent_doc_memory_io::closeout::capture_tsift_memory_closeout",
        "agent_doc_lease_io::local_model::reap_local_model_leases",
        "agent_doc_plugin_owner_io::stale_cleanup::reap_stale_jetbrains_for_file",
    ] {
        assert!(
            hooks_io.contains(required),
            "agent-doc-hooks-io must own the post-response hook effects adapter: {required}"
        );
    }
    for forbidden in [
        "agent_kit::hooks",
        "HookRegistry",
        "std::process::Command::new(\"sh\")",
        "post_response_hook_effects() -> impl agent_doc_hooks_io::PostResponseHookEffects",
        "default_post_response_hook_effects()",
        "pub fn fire_doc_hooks(",
        "pub fn fire_doc_event(",
        "pub fn fire_claim(",
        "pub fn fire_layout_change(",
        "pub fn poll(",
    ] {
        assert!(
            !orchestration_lib.contains(forbidden),
            "orchestration hook bridge must not re-own hook dispatch IO: {forbidden}"
        );
    }

    for (relative, required) in [
        (
            "agent-doc-stream-io/src/lib.rs",
            "effects.fire_post_write(file, &session_id)",
        ),
        (
            "src/main.rs",
            "agent_doc_hooks_io::fire_post_write_with_effects(",
        ),
        (
            "agent-doc-orchestration/src/write/run_entry.rs",
            "agent_doc_hooks_io::fire_post_write_with_effects(",
        ),
        (
            "agent-doc-commit-io/src/lib.rs",
            "agent_doc_hooks_io::fire_post_commit(file, session_id, None)",
        ),
        (
            "src/main.rs",
            "agent_doc_hooks_io::fire_doc_event(file, \"post_write\")",
        ),
        (
            "agent-doc-orchestration/src/write/run_entry.rs",
            "agent_doc_hooks_io::fire_doc_event(file, \"post_write\")",
        ),
        (
            "agent-doc-commit-io/src/lib.rs",
            "agent_doc_hooks_io::fire_doc_event(file, event)",
        ),
        (
            "agent-doc-start-io/src/lib.rs",
            "agent_doc_hooks_io::fire_doc_hooks(",
        ),
        (
            "agent-doc-orchestration/src/start/supervisor_io.rs",
            "use agent_doc_hooks_io::fire_doc_hooks;",
        ),
        (
            "agent-doc-orchestration/src/start.rs",
            "use agent_doc_hooks_io::fire_doc_hooks;",
        ),
    ] {
        let source = fs::read_to_string(manifest_dir.join(relative)).unwrap();
        assert!(
            source.contains(required),
            "{relative} should call focused hook IO directly: {required}"
        );
    }
}

#[test]
fn test_state_backbone_extraction_stays_first_class_and_facade_free() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let workspace_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    let workspace: toml::Value = toml::from_str(&workspace_manifest).unwrap();
    let package_version = workspace["package"]["version"].as_str();
    let members = workspace["workspace"]["members"].as_array().unwrap();

    assert!(
        members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-state-backbone")),
        "agent-doc-state-backbone must stay a first-class workspace crate"
    );
    assert!(
        members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-state-observer-io")),
        "agent-doc-state-observer-io must stay a first-class workspace crate"
    );

    let root_dependencies = workspace["dependencies"].as_table().unwrap();
    let root_dependency = root_dependencies["agent-doc-state-backbone"]
        .as_table()
        .unwrap();
    assert_eq!(
        root_dependency.get("path").and_then(toml::Value::as_str),
        Some("agent-doc-state-backbone")
    );
    assert_eq!(
        root_dependency.get("version").and_then(toml::Value::as_str),
        package_version
    );
    let root_observer_dependency = root_dependencies["agent-doc-state-observer-io"]
        .as_table()
        .unwrap();
    assert_eq!(
        root_observer_dependency
            .get("path")
            .and_then(toml::Value::as_str),
        Some("agent-doc-state-observer-io")
    );
    assert_eq!(
        root_observer_dependency
            .get("version")
            .and_then(toml::Value::as_str),
        package_version
    );

    let state_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-state-backbone/Cargo.toml")).unwrap();
    let state_crate: toml::Value = toml::from_str(&state_manifest).unwrap();
    let state_dependencies = state_crate["dependencies"].as_table().unwrap();
    assert!(
        !state_dependencies.contains_key("agent-doc-orchestration"),
        "state backbone must stay free of orchestration/effect dependencies"
    );
    let observer_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-state-observer-io/Cargo.toml")).unwrap();
    let observer_crate: toml::Value = toml::from_str(&observer_manifest).unwrap();
    let observer_dependencies = observer_crate["dependencies"].as_table().unwrap();
    assert!(
        observer_dependencies.contains_key("agent-doc-state-backbone")
            && observer_dependencies.contains_key("agent-doc-ops-log-io")
            && !observer_dependencies.contains_key("agent-doc-orchestration"),
        "state observer IO should adapt focused state backbone facts to ops-log output without depending on orchestration"
    );

    let orchestration_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/Cargo.toml")).unwrap();
    let orchestration: toml::Value = toml::from_str(&orchestration_manifest).unwrap();
    let orchestration_dependency = orchestration["dependencies"]["agent-doc-state-backbone"]
        .as_table()
        .unwrap();
    assert_eq!(
        orchestration_dependency
            .get("path")
            .and_then(toml::Value::as_str),
        Some("../agent-doc-state-backbone")
    );
    assert_eq!(
        orchestration_dependency
            .get("version")
            .and_then(toml::Value::as_str),
        package_version
    );
    let orchestration_observer_dependency =
        orchestration["dependencies"]["agent-doc-state-observer-io"]
            .as_table()
            .unwrap();
    assert_eq!(
        orchestration_observer_dependency
            .get("path")
            .and_then(toml::Value::as_str),
        Some("../agent-doc-state-observer-io")
    );
    assert_eq!(
        orchestration_observer_dependency
            .get("version")
            .and_then(toml::Value::as_str),
        package_version
    );

    assert!(
        !manifest_dir
            .join("agent-doc-orchestration/src/state_backbone.rs")
            .exists(),
        "orchestration must not keep a state_backbone source module facade"
    );
    assert!(
        !manifest_dir
            .join("agent-doc-orchestration/src/adstatechart_snapshot.rs")
            .exists(),
        "orchestration must not keep an adstatechart_snapshot observer facade"
    );
    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    assert!(
        !orchestration_lib.contains("pub mod state_backbone"),
        "orchestration must not re-export state_backbone as a compatibility facade"
    );
    assert!(
        !orchestration_lib.contains("pub mod adstatechart_snapshot"),
        "orchestration must not re-export adstatechart observer IO as a compatibility facade"
    );

    for relative_path in [
        "src/orchestrate.rs",
        "src/ffi.rs",
        "src/sim_world.rs",
        "tests/run_integration.rs",
    ] {
        let source = fs::read_to_string(manifest_dir.join(relative_path)).unwrap();
        assert!(
            !source.contains("agent_doc_orchestration::state_backbone"),
            "{relative_path} must use agent_doc_state_backbone directly"
        );
    }
}

#[test]
fn test_state_wire_extraction_stays_first_class_and_facade_free() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let workspace_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    let workspace: toml::Value = toml::from_str(&workspace_manifest).unwrap();
    let package_version = workspace["package"]["version"].as_str();
    let members = workspace["workspace"]["members"].as_array().unwrap();

    assert!(
        members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-state-wire")),
        "agent-doc-state-wire must stay a first-class workspace crate"
    );

    let root_dependencies = workspace["dependencies"].as_table().unwrap();
    let root_dependency = root_dependencies["agent-doc-state-wire"]
        .as_table()
        .unwrap();
    assert_eq!(
        root_dependency.get("path").and_then(toml::Value::as_str),
        Some("agent-doc-state-wire")
    );
    assert_eq!(
        root_dependency.get("version").and_then(toml::Value::as_str),
        package_version
    );

    let state_wire_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-state-wire/Cargo.toml")).unwrap();
    let state_wire: toml::Value = toml::from_str(&state_wire_manifest).unwrap();
    let state_wire_dependencies = state_wire["dependencies"].as_table().unwrap();
    assert!(
        state_wire_dependencies.contains_key("agent-doc-state-backbone"),
        "state wire must consume the extracted state backbone directly"
    );
    for forbidden_dependency in ["agent-doc-orchestration", "agent-doc-workflow"] {
        assert!(
            !state_wire_dependencies.contains_key(forbidden_dependency),
            "state wire must stay free of orchestration/workflow facade dependencies: {forbidden_dependency}"
        );
    }

    for removed_module in [
        "agent-doc-orchestration/src/state_wire.rs",
        "agent-doc-workflow/src/state_wire.rs",
    ] {
        assert!(
            !manifest_dir.join(removed_module).exists(),
            "{removed_module} must not remain as a state-wire facade module"
        );
    }

    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    assert!(
        !orchestration_lib.contains("pub mod state_wire"),
        "orchestration must not re-export state_wire as a compatibility facade"
    );
    let workflow_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-workflow/src/lib.rs")).unwrap();
    assert!(
        !workflow_lib.contains("pub mod state_wire"),
        "workflow must not re-export state_wire as a compatibility facade"
    );

    let ffi_source = fs::read_to_string(manifest_dir.join("src/ffi.rs")).unwrap();
    assert!(
        ffi_source.contains("agent_doc_state_wire::subscribe"),
        "FFI subscribe path must call the focused state-wire crate directly"
    );
    assert!(
        !ffi_source.contains("agent_doc_orchestration::state_wire")
            && !ffi_source.contains("agent_doc_workflow::state_wire"),
        "FFI subscribe path must not use removed state-wire facades"
    );
}

#[test]
fn test_turn_scope_io_extraction_stays_first_class_and_facade_free() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let workspace_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    let workspace: toml::Value = toml::from_str(&workspace_manifest).unwrap();
    let package_version = workspace["package"]["version"].as_str();
    let members = workspace["workspace"]["members"].as_array().unwrap();

    assert!(
        members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-turn-scope-io")),
        "agent-doc-turn-scope-io must stay a first-class workspace crate"
    );

    let root_dependencies = workspace["dependencies"].as_table().unwrap();
    let root_dependency = root_dependencies["agent-doc-turn-scope-io"]
        .as_table()
        .unwrap();
    assert_eq!(
        root_dependency.get("path").and_then(toml::Value::as_str),
        Some("agent-doc-turn-scope-io")
    );
    assert_eq!(
        root_dependency.get("version").and_then(toml::Value::as_str),
        package_version
    );

    let turn_scope_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-turn-scope-io/Cargo.toml")).unwrap();
    let turn_scope: toml::Value = toml::from_str(&turn_scope_manifest).unwrap();
    let turn_scope_dependencies = turn_scope["dependencies"].as_table().unwrap();
    assert!(
        turn_scope_dependencies.contains_key("agent-doc-turn")
            && turn_scope_dependencies.contains_key("agent-doc-fs"),
        "turn-scope IO must depend only on turn models plus filesystem path helpers"
    );
    for forbidden_dependency in ["agent-doc-core", "agent-doc-orchestration"] {
        assert!(
            !turn_scope_dependencies.contains_key(forbidden_dependency),
            "turn-scope IO must not depend on removed core/orchestration facades: {forbidden_dependency}"
        );
    }

    assert!(
        !manifest_dir
            .join("agent-doc-orchestration/src/turn_scope_store.rs")
            .exists(),
        "orchestration must not keep a turn_scope_store facade module"
    );
    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    assert!(
        !orchestration_lib.contains("pub mod turn_scope_store"),
        "orchestration must not export a turn_scope_store facade"
    );
    for relative_path in [
        "agent-doc-run-io/src/lib.rs",
        "agent-doc-commit-io/src/lib.rs",
        "agent-doc-orchestration/src/preflight/run.rs",
        "agent-doc-write-converge-io/src/convergence_fixture_tests.rs",
        "tests/run_integration.rs",
    ] {
        let source = fs::read_to_string(manifest_dir.join(relative_path)).unwrap();
        assert!(
            source.contains("agent_doc_turn_scope_io::"),
            "{relative_path} must call the focused turn-scope IO crate directly"
        );
        assert!(
            !source.contains("crate::turn_scope_store")
                && !source.contains("agent_doc_orchestration::turn_scope_store"),
            "{relative_path} must not use the removed orchestration turn-scope facade"
        );
    }
}

#[test]
fn test_agent_doc_model_tier_owns_context_usage_policy() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let workspace_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    let workspace: toml::Value = toml::from_str(&workspace_manifest).unwrap();
    let package_version = workspace["package"]["version"].as_str();
    let members = workspace["workspace"]["members"].as_array().unwrap();

    assert!(
        members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-model-tier")),
        "agent-doc-model-tier must stay a first-class workspace crate"
    );

    let model_tier_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-model-tier/Cargo.toml")).unwrap();
    let parsed: toml::Value = toml::from_str(&model_tier_manifest).unwrap();
    let dependencies = parsed["dependencies"].as_table().unwrap();
    assert!(
        dependencies.contains_key("serde_json"),
        "context transcript token parsing belongs in agent-doc-model-tier and needs serde_json"
    );
    for forbidden in [
        "agent-doc-core",
        "agent-doc-orchestration",
        "git2",
        "interprocess",
        "notify",
        "rusqlite",
        "tmux-router",
    ] {
        assert!(
            !dependencies.contains_key(forbidden),
            "agent-doc-model-tier context usage policy must stay free of core, orchestration, git, editor IPC, sqlite, or tmux crates"
        );
    }

    let orchestration_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/Cargo.toml")).unwrap();
    let orchestration: toml::Value = toml::from_str(&orchestration_manifest).unwrap();
    let orchestration_dependencies = orchestration["dependencies"].as_table().unwrap();
    let dependency = orchestration_dependencies["agent-doc-model-tier"]
        .as_table()
        .unwrap();
    assert_eq!(
        dependency.get("path").and_then(toml::Value::as_str),
        Some("../agent-doc-model-tier")
    );
    assert_eq!(
        dependency.get("version").and_then(toml::Value::as_str),
        package_version
    );

    let model_tier_source =
        fs::read_to_string(manifest_dir.join("agent-doc-model-tier/src/lib.rs")).unwrap();
    for required_snippet in [
        "pub fn canonical_harness_name(",
        "pub const HARNESS_MISMATCH_WARNING_CODE",
        "pub struct HarnessMismatchWarning",
        "pub fn harness_mismatch_warning(",
        "pub const CODEX_NETWORK_ACCESS_NON_CODEX_HARNESS_WARNING_CODE",
        "pub struct CodexNetworkAccessNonCodexHarnessWarning",
        "pub fn codex_network_access_non_codex_harness_warning(",
        "pub fn short_model_name(",
        "pub fn resolve_agent_model(",
    ] {
        assert!(
            model_tier_source.contains(required_snippet),
            "agent-doc-model-tier should own preflight model attribution and harness policy directly: {required_snippet}"
        );
    }

    let context_usage =
        fs::read_to_string(manifest_dir.join("agent-doc-model-tier/src/context_usage.rs")).unwrap();
    for required_snippet in [
        "pub enum Harness",
        "pub struct UsedTokens",
        "pub const CLAUDE_CONTEXT_WINDOW",
        "pub fn claude_project_hash(",
        "pub fn claude_transcript_path(",
        "pub fn claude_projects_subdir(",
        "pub fn parse_claude_jsonl_used_tokens(",
        "pub fn context_window_for_model(",
        "pub fn context_pct(",
        "pub enum TranscriptContextPctDiagnostic",
        "pub struct TranscriptContextPct",
        "pub fn transcript_context_pct_from_content(",
        "pub fn parse_codex_jsonl_context_pct(",
        "pub fn parse_codex_jsonl_session_meta_cwd(",
        "pub struct ClearDecision",
        "pub fn clear_decision(",
    ] {
        assert!(
            context_usage.contains(required_snippet),
            "agent-doc-model-tier should own context usage policy directly: {required_snippet}"
        );
    }

    let context_transcript_io =
        fs::read_to_string(manifest_dir.join("agent-doc-model-tier/src/context_transcript_io.rs"))
            .unwrap();
    for required_snippet in [
        "pub fn read_used_tokens(",
        "pub fn transcript_context_pct(",
        "pub fn latest_claude_transcript(",
        "pub fn latest_codex_transcript(",
    ] {
        assert!(
            context_transcript_io.contains(required_snippet),
            "agent-doc-model-tier should own transcript locator/read IO directly: {required_snippet}"
        );
    }

    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    let orchestration_context_path =
        manifest_dir.join("agent-doc-orchestration/src/context_pct.rs");
    assert!(
        !orchestration_context_path.exists(),
        "orchestration must not keep a context_pct adapter module after transcript IO extraction"
    );
    let preflight_source =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/preflight.rs")).unwrap();
    let preflight_run_source =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/preflight/run.rs"))
            .unwrap();
    let preflight_warnings_source =
        fs::read_to_string(manifest_dir.join("agent-doc-preflight-io/src/warnings.rs")).unwrap();
    for forbidden_snippet in [
        "fn canonical_harness_name(",
        "fn harness_mismatch_warning(",
        "fn codex_network_access_non_codex_harness_warning(",
        "fn short_model_name(",
        "fn resolve_agent_model(",
    ] {
        assert!(
            !preflight_source.contains(forbidden_snippet),
            "preflight.rs must not re-own model-tier attribution or harness policy: {forbidden_snippet}"
        );
        assert!(
            !preflight_run_source.contains(forbidden_snippet),
            "preflight/run.rs must not re-own model-tier attribution or harness policy: {forbidden_snippet}"
        );
    }
    assert!(
        preflight_warnings_source.contains("agent_doc_model_tier::harness_mismatch_warning(")
            && preflight_warnings_source
                .contains("agent_doc_model_tier::codex_network_access_non_codex_harness_warning(")
            && preflight_run_source.contains("agent_doc_model_tier::resolve_agent_model("),
        "preflight runtime/warnings should adapt preflight facts into focused model-tier policy directly"
    );
    assert!(
        preflight_source.contains("agent_doc_model_tier::canonical_harness_name("),
        "preflight tests should call focused model-tier canonical harness policy directly"
    );
    for forbidden_snippet in [
        "pub enum Harness",
        "pub struct UsedTokens",
        "pub const CLAUDE_CONTEXT_WINDOW",
        "pub fn claude_project_hash(",
        "pub fn claude_transcript_path(",
        "pub fn claude_projects_subdir(",
        "pub fn parse_claude_jsonl_used_tokens(",
        "pub fn context_window_for_model(",
        "pub fn context_pct(",
        "pub enum TranscriptContextPctDiagnostic",
        "pub struct TranscriptContextPct",
        "pub fn transcript_context_pct_from_content(",
        "pub fn parse_codex_jsonl_context_pct(",
        "pub fn parse_codex_jsonl_session_meta_cwd(",
        "pub struct ClearDecision",
        "pub fn clear_decision(",
    ] {
        assert!(
            !orchestration_lib.contains(forbidden_snippet),
            "orchestration lib must not expose context usage policy or transcript IO: {forbidden_snippet}"
        );
    }
    assert!(
        !orchestration_lib.contains("pub mod context_pct;"),
        "orchestration must not keep a context_pct adapter module after transcript IO extraction"
    );

    let codex_hook_io =
        fs::read_to_string(manifest_dir.join("agent-doc-codex-hook-io/src/lib.rs")).unwrap();
    assert!(
        codex_hook_io.contains("use agent_doc_model_tier::context_usage::{")
            && codex_hook_io.contains("use agent_doc_model_tier::context_transcript_io::{")
            && codex_hook_io.contains("clear_decision")
            && codex_hook_io.contains("Harness"),
        "focused Codex hook IO should use focused context usage policy and transcript IO directly"
    );
    let codex_hook =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/codex_hook.rs")).unwrap();
    assert!(
        !codex_hook.contains("agent_doc_model_tier::context_usage")
            && !codex_hook.contains("agent_doc_model_tier::context_transcript_io")
            && !codex_hook.contains("clear_decision"),
        "orchestration Codex Stop handler must not re-own context usage policy or transcript IO"
    );
}

