#[test]
fn test_agent_doc_queue_owns_do_directive_target_parsing() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let queue_directive =
        fs::read_to_string(manifest_dir.join("agent-doc-queue/src/queue_directive.rs")).unwrap();
    for required in [
        "pub fn explicit_do_directive_target_id",
        "pub fn explicit_do_directive_target_ids",
        "pub fn first_directive_target_id",
        "pub fn do_directive_target_ids",
        "pub fn do_directive_target_ids_in_line",
        "pub fn filter_expect_done_or_gate_ids",
        "fn leads_with_bare_id_token",
    ] {
        assert!(
            queue_directive.contains(required),
            "agent-doc-queue must own id-backed queue directive parsing: {required}"
        );
    }

    let backlog_source =
        fs::read_to_string(manifest_dir.join("agent-doc-element-backlog/src/backlog.rs")).unwrap();
    assert!(
        backlog_source.contains("pub fn extract_pending_hash_ids"),
        "ordered tracked-work #id scanning should live with backlog/tracked-work parsing"
    );

    let done_signals_path =
        manifest_dir.join("agent-doc-orchestration/src/session_check/done_signals.rs");
    assert!(
        !done_signals_path.exists(),
        "session_check/done_signals.rs must stay deleted instead of becoming an orchestration facade"
    );
    let closeout_signal =
        fs::read_to_string(manifest_dir.join("agent-doc-turn/src/closeout_signal.rs")).unwrap();
    for forbidden in [
        "pub fn do_directive_target_ids",
        "pub(crate) fn do_directive_target_ids_in_line",
        "pub(crate) fn extract_pending_hash_ids",
        "pub(crate) fn leads_with_bare_id_token",
    ] {
        assert!(
            !closeout_signal.contains(forbidden),
            "closeout signal policy must not re-own queue directive parsing: {forbidden}"
        );
    }
    assert!(
        closeout_signal.contains("agent_doc_element_backlog::backlog::extract_pending_hash_ids"),
        "done signal parsing should reuse the focused tracked-work #id scanner from agent-doc-turn"
    );

    let tsift_graph = fs::read_to_string(manifest_dir.join("src/tsift_graph.rs")).unwrap();
    for forbidden in [
        "pub(crate) fn extract_do_target",
        "pub(crate) fn extract_do_targets",
        "fn extract_hash_ids",
    ] {
        assert!(
            !tsift_graph.contains(forbidden),
            "root tsift_graph must not re-own queue directive target parsing: {forbidden}"
        );
    }
    assert!(
        tsift_graph.contains("agent_doc_queue::queue_directive::explicit_do_directive_target_id"),
        "root tsift graph should call focused explicit-do target parsing directly"
    );
    for relative in ["src/plan.rs", "src/jobs.rs"] {
        let source = fs::read_to_string(manifest_dir.join(relative)).unwrap();
        assert!(
            source.contains("agent_doc_queue::queue_directive::explicit_do_directive_target_ids"),
            "{relative} should call focused explicit-do target parsing directly"
        );
        assert!(
            !source.contains("crate::tsift_graph::extract_do_targets"),
            "{relative} must not route explicit-do target parsing through tsift_graph"
        );
    }

    let preflight_run =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/preflight/run.rs"))
            .unwrap();
    assert!(
        preflight_run.contains("agent_doc_queue::queue_directive::do_directive_target_ids"),
        "preflight/run.rs should call focused queue directive parsing directly"
    );
    assert!(
        !preflight_run.contains("crate::session_check::do_directive_target_ids"),
        "preflight/run.rs must not route queue directive parsing through session_check"
    );
    let response_guards =
        fs::read_to_string(manifest_dir.join("agent-doc-session-check-io/src/response_guards.rs"))
            .unwrap();
    assert!(
        response_guards
            .contains("agent_doc_turn::closeout_signal::still_missing_dropped_queue_prompts"),
        "response_guards should route dropped-queue prompt classification through focused closeout_signal policy"
    );
    let closeout_signal =
        fs::read_to_string(manifest_dir.join("agent-doc-turn/src/closeout_signal.rs")).unwrap();
    assert!(
        closeout_signal.contains("agent_doc_queue::queue_directive::do_directive_target_ids"),
        "closeout_signal should call focused queue directive parsing directly"
    );
    assert!(
        !response_guards.contains("crate::session_check::do_directive_target_ids"),
        "response_guards must not route queue directive parsing through session_check"
    );
    let project_controller =
        fs::read_to_string(manifest_dir.join("agent-doc-controller-io/src/project_controller.rs"))
            .unwrap();
    assert!(
        project_controller.contains("agent_doc_queue::queue_directive::first_directive_target_id"),
        "project_controller should call focused first queue directive target parsing directly"
    );
    assert!(
        !project_controller.contains("fn queue_head_id_from_prompt("),
        "project_controller must not keep a local queue directive parsing wrapper"
    );
    let queue_closeout_guard =
        fs::read_to_string(manifest_dir.join("agent-doc-queue/src/queue_closeout_guard.rs"))
            .unwrap();
    assert!(
        queue_closeout_guard.contains("queue_directive::do_directive_target_ids"),
        "queue closeout guard policy should call focused queue directive parsing directly"
    );
    let preflight_maintenance =
        fs::read_to_string(manifest_dir.join("agent-doc-preflight-io/src/lib.rs")).unwrap();
    assert!(
        !preflight_maintenance.contains("fn filter_expect_done_or_gate_ids"),
        "preflight maintenance must not re-own queue directive lifecycle expectation policy"
    );
    let preflight_run =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/preflight/run.rs"))
            .unwrap();
    assert!(
        preflight_run.contains("agent_doc_queue::queue_directive::filter_expect_done_or_gate_ids"),
        "preflight run should call focused queue directive lifecycle expectation policy directly"
    );
    let queue_head_guards = fs::read_to_string(
        manifest_dir.join("agent-doc-session-check-io/src/queue_head_guards.rs"),
    )
    .unwrap();
    assert!(
        !queue_head_guards.contains("agent_doc_queue::queue_directive::do_directive_target_ids"),
        "queue_head_guards should consume queue_closeout_guard policy instead of parsing queue directives directly"
    );
    let queue_head_provenance_guards = fs::read_to_string(
        manifest_dir.join("agent-doc-session-check-io/src/queue_head_provenance_guards.rs"),
    )
    .unwrap();
    assert!(
        !queue_head_provenance_guards
            .contains("agent_doc_queue::queue_directive::do_directive_target_ids"),
        "queue_head_provenance_guards should consume queue_closeout_guard policy instead of parsing queue directives directly"
    );
}

