#[test]
fn test_agent_doc_turn_owns_turn_status_policy() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let turn_status =
        fs::read_to_string(manifest_dir.join("agent-doc-turn/src/turn_status.rs")).unwrap();
    for required in [
        "pub const TURN_ACTIVE_PANE_TITLE",
        "pub const STALE_SUPERVISOR_PANE_MARKER",
        "pub const STALE_SUPERVISOR_MARKER",
        "pub const TURN_ACTIVE_MARKER",
        "pub const TURN_ACTIVE_TTL_SECS",
        "pub struct TurnActiveMarker",
        "pub fn turn_active_marker_is_fresh",
        "pub fn turn_active_marker_matches_pane",
        "pub fn pane_title_for_state",
        "pub fn pane_title_for_status",
    ] {
        assert!(
            turn_status.contains(required),
            "agent-doc-turn must own turn-status policy vocabulary: {required}"
        );
    }

    let turn_lib = fs::read_to_string(manifest_dir.join("agent-doc-turn/src/lib.rs")).unwrap();
    assert!(
        turn_lib.contains("pub mod turn_status;"),
        "agent-doc-turn should expose turn-status policy through its owning module"
    );
    assert!(
        !turn_lib.contains("pub use turn_status"),
        "agent-doc-turn should not add a turn_status root facade"
    );

    let workspace_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    assert!(
        workspace_manifest.contains("\"agent-doc-turn-status-io\""),
        "agent-doc-turn-status-io should be a workspace member"
    );
    assert!(
        workspace_manifest
            .contains("agent-doc-turn-status-io = { path = \"agent-doc-turn-status-io\""),
        "CLI shell should depend on turn-status IO directly"
    );

    let turn_status_io =
        fs::read_to_string(manifest_dir.join("agent-doc-turn-status-io/src/lib.rs")).unwrap();
    let turn_status_io_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-turn-status-io/Cargo.toml")).unwrap();
    let turn_status_io_manifest: toml::Value = toml::from_str(&turn_status_io_manifest).unwrap();
    let turn_status_io_dependencies = turn_status_io_manifest["dependencies"].as_table().unwrap();
    assert!(
        turn_status_io_dependencies.contains_key("agent-doc-project-root-io"),
        "turn-status IO should delegate marker root discovery through project-root IO"
    );
    assert!(
        !turn_status_io_dependencies.contains_key("agent-doc-fs"),
        "turn-status IO should not own direct filesystem project-root discovery"
    );
    for forbidden in [
        "pub const TURN_ACTIVE_PANE_TITLE",
        "pub const STALE_SUPERVISOR_PANE_MARKER",
        "pub const STALE_SUPERVISOR_MARKER",
        "pub const TURN_ACTIVE_MARKER",
        "pub const TURN_ACTIVE_TTL_SECS",
        "pub struct TurnActiveMarker",
        "pub fn pane_title_for_state",
        "pub fn pane_title_for_status",
        "pub use agent_doc_turn::turn_status",
    ] {
        assert!(
            !turn_status_io.contains(forbidden),
            "turn-status IO must stay an effect adapter, not a policy facade: {forbidden}"
        );
    }
    for required in [
        "agent_doc_turn::turn_status::{",
        "TurnActiveMarker",
        "pane_title_for_status",
        "turn_active_marker_is_fresh",
        "turn_active_marker_matches_pane",
        "read_turn_active_marker_for_file",
        "agent_doc_project_root_io::project_root_containing(",
        "agent_doc_project_root_io::project_root_from_cwd(",
    ] {
        assert!(
            turn_status_io.contains(required),
            "turn-status IO should call focused turn-status policy directly: {required}"
        );
    }
    assert!(
        !turn_status_io.contains("agent_doc_fs::find_project_root("),
        "turn-status IO should delegate project-root resolution through project-root IO"
    );
    assert!(
        !turn_status_io.contains("agent_doc_orchestration::"),
        "turn-status IO must not reach back through orchestration"
    );

    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    assert!(
        !orchestration_lib.contains("pub mod turn_status;"),
        "orchestration must not expose a turn_status facade"
    );

    let main = fs::read_to_string(manifest_dir.join("src/main.rs")).unwrap();
    assert!(
        main.contains("agent_doc_turn_status_io::run(true)")
            && main.contains("agent_doc_turn_status_io::run(false)"),
        "turn-status command should call the focused IO crate directly"
    );
    let session_actor_cmd =
        fs::read_to_string(manifest_dir.join("src/session_actor_cmd.rs")).unwrap();
    assert!(
        session_actor_cmd.contains("agent_doc_turn_status_io::read_turn_active_marker"),
        "session actor command should read turn-active markers through the focused IO crate"
    );
    for relative_path in [
        "agent-doc-orchestration/src/start.rs",
        "agent-doc-orchestration/src/start/idle_watch.rs",
    ] {
        let source = fs::read_to_string(manifest_dir.join(relative_path)).unwrap();
        assert!(
            source.contains("agent_doc_turn_status_io::"),
            "{relative_path} should call turn-status IO directly"
        );
    }
    let start_source =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/start.rs")).unwrap();
    assert!(
        !start_source.contains("agent_doc_fs::find_project_root(")
            && start_source.contains("agent_doc_turn_status_io::read_turn_active_marker_for_file("),
        "start.rs should ask turn-status IO for file-scoped marker reads instead of owning root discovery"
    );
}

#[test]
fn test_agent_doc_turn_owns_owner_pane_recursion_diagnostics() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    assert!(
        manifest_dir
            .join("agent-doc-turn/src/owner_pane_recursion.rs")
            .exists(),
        "owner-pane self-invocation diagnostic policy should live in the focused turn crate"
    );

    let turn_source =
        fs::read_to_string(manifest_dir.join("agent-doc-turn/src/owner_pane_recursion.rs"))
            .unwrap();
    for required in [
        "pub struct OwnerPaneQueueHead",
        "pub const OWNER_PANE_WEDGE_THRESHOLD",
        "pub struct OwnerPaneWedgeRecord",
        "pub fn record_owner_pane_wedge_fire",
        "pub fn owner_pane_wedge_threshold_reached",
        "pub fn recursive_direct_invocation_message",
        "pub fn recursive_start_invocation_message",
        "pub fn prompt_miss_message",
        "pub fn queue_handoff_message",
        "pub fn queue_wedge_halt_message",
    ] {
        assert!(
            turn_source.contains(required),
            "agent-doc-turn must own owner-pane recursion diagnostic policy: {required}"
        );
    }

    let turn_lib = fs::read_to_string(manifest_dir.join("agent-doc-turn/src/lib.rs")).unwrap();
    assert!(
        turn_lib.contains("pub mod owner_pane_recursion;"),
        "agent-doc-turn should expose owner-pane recursion diagnostics through the owning module"
    );
    assert!(
        !turn_lib.contains("pub use owner_pane_recursion"),
        "agent-doc-turn should not add an owner_pane_recursion root facade"
    );

    let workspace_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    let workspace: toml::Value = toml::from_str(&workspace_manifest).unwrap();
    let package_version = workspace["package"]["version"].as_str();
    let members = workspace["workspace"]["members"].as_array().unwrap();
    assert!(
        members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-owner-pane-io")),
        "agent-doc-owner-pane-io must stay a first-class workspace crate"
    );
    let root_dependencies = workspace["dependencies"].as_table().unwrap();
    let root_dependency = root_dependencies["agent-doc-owner-pane-io"]
        .as_table()
        .unwrap();
    assert_eq!(
        root_dependency.get("path").and_then(toml::Value::as_str),
        Some("agent-doc-owner-pane-io")
    );
    assert_eq!(
        root_dependency.get("version").and_then(toml::Value::as_str),
        package_version
    );

    let owner_pane_io_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-owner-pane-io/Cargo.toml")).unwrap();
    let owner_pane_io_crate: toml::Value = toml::from_str(&owner_pane_io_manifest).unwrap();
    let owner_pane_io_dependencies = owner_pane_io_crate["dependencies"].as_table().unwrap();
    assert!(
        owner_pane_io_dependencies.contains_key("agent-doc-turn")
            && owner_pane_io_dependencies.contains_key("agent-doc-fs"),
        "owner-pane IO must depend on turn policy and filesystem path helpers directly"
    );
    for forbidden_dependency in ["agent-doc-core", "agent-doc-orchestration"] {
        assert!(
            !owner_pane_io_dependencies.contains_key(forbidden_dependency),
            "owner-pane IO must not depend on core/orchestration facades: {forbidden_dependency}"
        );
    }

    let orchestration_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/Cargo.toml")).unwrap();
    let orchestration: toml::Value = toml::from_str(&orchestration_manifest).unwrap();
    let orchestration_dependency = orchestration["dependencies"]["agent-doc-owner-pane-io"]
        .as_table()
        .unwrap();
    assert_eq!(
        orchestration_dependency
            .get("path")
            .and_then(toml::Value::as_str),
        Some("../agent-doc-owner-pane-io")
    );
    assert_eq!(
        orchestration_dependency
            .get("version")
            .and_then(toml::Value::as_str),
        package_version
    );

    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    assert!(
        !manifest_dir
            .join("agent-doc-orchestration/src/owner_pane_wedge_counter.rs")
            .exists(),
        "orchestration must not keep an owner_pane_wedge_counter source module facade"
    );
    assert!(
        !orchestration_lib.contains("pub mod owner_pane_wedge_counter;"),
        "orchestration must not expose an owner-pane wedge-counter IO facade"
    );

    let direct_run_tests =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/tests/direct_run.rs"))
            .unwrap();
    let run_io_source =
        fs::read_to_string(manifest_dir.join("agent-doc-run-io/src/lib.rs")).unwrap();
    let owner_pane_io =
        fs::read_to_string(manifest_dir.join("agent-doc-owner-pane-io/src/lib.rs")).unwrap();
    assert!(
        !manifest_dir
            .join("agent-doc-orchestration/src/recguard_wedge.rs")
            .exists(),
        "old recguard_wedge module path should not remain as a compatibility alias"
    );
    for forbidden in [
        "fn format_recursive_start_diagnostic",
        "fn owned_pane_prompt_miss_diagnostic",
        "fn owned_pane_queue_handoff_diagnostic",
        "fn owned_pane_queue_wedge_halt_diagnostic",
        "recursive self-owned-pane start would deadlock:",
        "owned-pane self-invocation with unresolved exchange prompt:",
        "owned-pane self-invocation with active auto-queue head:",
        "owned-pane self-invocation WEDGE:",
        "managed owner-pane supervisor will submit",
    ] {
        assert!(
            !direct_run_tests.contains(forbidden),
            "orchestration direct-run tests must not re-own or facade owner-pane recursion diagnostics: {forbidden}"
        );
    }
    for forbidden in [
        "pub const WEDGE_THRESHOLD",
        "struct WedgeRecord",
        "pub fn is_wedged(",
        "pub fn threshold_reached(",
    ] {
        assert!(
            !owner_pane_io.contains(forbidden),
            "owner-pane IO must not re-own extracted owner-pane wedge policy: {forbidden}"
        );
    }
    for required in [
        "use agent_doc_turn::owner_pane_recursion::{",
        "OwnerPaneQueueHead",
        "owner_pane_wedge_threshold_reached",
        "prompt_miss_message",
        "queue_handoff_message",
        "queue_wedge_halt_message",
    ] {
        assert!(
            run_io_source.contains(required),
            "run IO should call focused owner-pane recursion diagnostics directly: {required}"
        );
    }
    for required in [
        "use agent_doc_turn::owner_pane_recursion::{",
        "recursive_direct_invocation_message",
        "recursive_start_invocation_message",
    ] {
        assert!(
            run_io_source.contains(required),
            "run IO should call focused recursive owner-pane diagnostics directly: {required}"
        );
    }
    for required in ["OwnerPaneWedgeRecord", "record_owner_pane_wedge_fire"] {
        assert!(
            owner_pane_io.contains(required),
            "owner-pane IO should persist focused owner-pane wedge records directly: {required}"
        );
    }
    for relative_path in [
        "agent-doc-run-io/src/lib.rs",
        "agent-doc-queue-io/src/queue_consume.rs",
        "agent-doc-orchestration/src/write/run_entry.rs",
    ] {
        let source = fs::read_to_string(manifest_dir.join(relative_path)).unwrap();
        assert!(
            source.contains("agent_doc_owner_pane_io::"),
            "{relative_path} should call owner-pane IO directly"
        );
        assert!(
            !source.contains("crate::owner_pane_wedge_counter"),
            "{relative_path} must not call an orchestration owner-pane wedge-counter facade"
        );
    }
}

