#[test]
fn test_agent_doc_session_check_io_owns_guard_adapters() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let workspace_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    let workspace: toml::Value = toml::from_str(&workspace_manifest).unwrap();
    let members = workspace["workspace"]["members"].as_array().unwrap();
    assert!(
        members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-session-check-io")),
        "agent-doc-session-check-io must stay a first-class workspace crate"
    );

    let orchestration_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/Cargo.toml")).unwrap();
    let orchestration: toml::Value = toml::from_str(&orchestration_manifest).unwrap();
    assert!(
        orchestration["dependencies"]
            .as_table()
            .unwrap()
            .contains_key("agent-doc-session-check-io"),
        "orchestration should depend on the focused session-check IO crate"
    );

    for old_path in [
        "agent-doc-orchestration/src/session_check/backlog_guards.rs",
        "agent-doc-orchestration/src/session_check/partial_staging.rs",
        "agent-doc-orchestration/src/session_check/queue_head_guards.rs",
        "agent-doc-orchestration/src/session_check/queue_head_provenance_guards.rs",
        "agent-doc-orchestration/src/session_check/detect.rs",
        "agent-doc-orchestration/src/session_check/pending_guards.rs",
        "agent-doc-orchestration/src/session_check/closeout_guards.rs",
        "agent-doc-orchestration/src/session_check/response_guards.rs",
    ] {
        assert!(
            !manifest_dir.join(old_path).exists(),
            "orchestration must not keep moved session-check guard adapter source: {old_path}"
        );
    }

    for new_path in [
        "agent-doc-session-check-io/src/backlog_guards.rs",
        "agent-doc-session-check-io/src/partial_staging.rs",
        "agent-doc-session-check-io/src/queue_head_guards.rs",
        "agent-doc-session-check-io/src/queue_head_provenance_guards.rs",
        "agent-doc-session-check-io/src/guard_modes.rs",
        "agent-doc-session-check-io/src/prompt_bearing.rs",
        "agent-doc-session-check-io/src/detect.rs",
        "agent-doc-session-check-io/src/pending_capture.rs",
        "agent-doc-session-check-io/src/pending_guards.rs",
        "agent-doc-session-check-io/src/closeout_guards.rs",
        "agent-doc-session-check-io/src/response_guards.rs",
    ] {
        assert!(
            manifest_dir.join(new_path).exists(),
            "focused session-check IO crate must own moved guard adapter source: {new_path}"
        );
    }

    assert!(
        !manifest_dir
            .join("agent-doc-orchestration/src/session_check.rs")
            .exists(),
        "orchestration must not keep the moved session_check source module"
    );
    let session_check =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/tests/session_check.rs"))
            .unwrap();
    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    assert!(
        !orchestration_lib.contains("pub mod session_check;")
            && !orchestration_lib.contains("mod session_check;")
            && !orchestration_lib.contains("pub fn session_check_effects()")
            && !orchestration_lib.contains(
                "impl agent_doc_session_check_io::SessionCheckEffects for OrchestrationSessionCheckEffects"
            ),
        "orchestration must delete the session_check source shim and runtime SessionCheckEffects port"
    );
    let closeout_runtime =
        fs::read_to_string(manifest_dir.join("agent-doc-closeout-runtime-io/src/lib.rs")).unwrap();
    assert!(
        closeout_runtime.contains("pub fn session_check_effects()")
            && closeout_runtime.contains(
                "impl agent_doc_session_check_io::SessionCheckEffects for RuntimeSessionCheckEffects"
            ),
        "agent-doc-closeout-runtime-io should own the session-check runtime effects port"
    );
    for production_source in [
        "src/main.rs",
        "src/mcp.rs",
        "agent-doc-orchestration/src/codex_hook.rs",
        "agent-doc-orchestration/src/preflight.rs",
        "agent-doc-orchestration/src/preflight/run.rs",
        "agent-doc-orchestration/src/repair.rs",
        "agent-doc-orchestration/src/route.rs",
        "agent-doc-orchestration/src/write.rs",
    ] {
        let source = fs::read_to_string(manifest_dir.join(production_source)).unwrap();
        assert!(
            !source.contains("crate::session_check::")
                && !source.contains("agent_doc_orchestration::session_check::"),
            "{production_source} must call agent-doc-session-check-io directly instead of the orchestration session_check facade"
        );
    }
    for forbidden in [
        "pub use agent_doc_session_check_io",
        "pub fn run_with_options(",
        "pub fn inspect(",
        "pub fn inspect_with_warnings(",
        "pub fn enforce_clean_closeout(",
        "mod backlog_guards;",
        "mod partial_staging;",
        "mod queue_head_guards;",
        "mod queue_head_provenance_guards;",
        "mod detect;",
        "mod pending_guards;",
        "mod closeout_guards;",
        "mod response_guards;",
    ] {
        assert!(
            !session_check.contains(forbidden),
            "moved orchestration session_check test must not retain moved guard module facade: {forbidden}"
        );
    }
    for required in [
        "agent_doc_session_check_io::inspect(",
        "agent_doc_session_check_io::inspect_with_warnings(",
        "&agent_doc_closeout_runtime_io::session_check_effects()",
        "agent_doc_session_check_io::run_with_options(",
        "agent_doc_session_check_io::enforce_clean_closeout(",
    ] {
        assert!(
            session_check.contains(required),
            "moved orchestration session-check tests should call focused command IO directly: {required}"
        );
    }
    let closeout_guards =
        fs::read_to_string(manifest_dir.join("agent-doc-session-check-io/src/closeout_guards.rs"))
            .unwrap();
    for forbidden in [
        "pub fn first_unstarted_prompt_bearing_change(",
        "pub fn detect_unstarted_prompt_bearing_diff(",
    ] {
        assert!(
            !closeout_guards.contains(forbidden),
            "session-check closeout guards must not retain moved prompt-bearing IO adapter: {forbidden}"
        );
    }
    let session_check_command =
        fs::read_to_string(manifest_dir.join("agent-doc-session-check-io/src/command.rs")).unwrap();
    assert!(
        session_check_command.contains("crate::check_shadow_backlog_guard")
            && session_check_command.contains("crate::check_free_text_queue_head_provenance")
            && session_check_command.contains("crate::check_parent_submodule_pointer_guard")
            && session_check_command.contains("crate::check_prompt_only_exchange_tail_guard")
            && session_check_command.contains("crate::check_pending_capture_guard")
            && session_check_command.contains("crate::check_pending_done_guard")
            && session_check_command.contains("crate::check_blocked_closeout_followup_guard")
            && session_check_command.contains("crate::check_dropped_exchange_prompt_guard")
            && session_check.contains("realtime_steering_since_turn_baseline"),
        "session-check command IO should call the focused guard adapters directly"
    );

    let write_source =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/write.rs")).unwrap();
    assert!(
        !write_source.contains("crate::session_check::resolve_"),
        "write.rs must not route guard-mode resolvers through orchestration session_check"
    );
    let pending_write_checks = fs::read_to_string(
        manifest_dir.join("agent-doc-session-check-io/src/write_pending_checks.rs"),
    )
    .unwrap();
    for required in [
        "crate::resolve_pending_capture_mode_with_force_disk",
        "crate::resolve_pending_done_mode_with_force_disk",
        "crate::resolve_review_done_guard_mode",
    ] {
        assert!(
            pending_write_checks.contains(required),
            "focused write pending checks should call crate-local guard-mode resolver: {required}"
        );
    }
    assert!(
        !pending_write_checks.contains("agent_doc_session_check_io::resolve_")
            && !pending_write_checks.contains("crate::session_check::resolve_"),
        "focused write pending checks must not route guard-mode resolvers through orchestration"
    );
}

#[test]
fn test_agent_doc_flow_io_owns_closeout_effect_adapter() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let workspace_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    let workspace: toml::Value = toml::from_str(&workspace_manifest).unwrap();
    let members = workspace["workspace"]["members"].as_array().unwrap();
    assert!(
        members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-flow-io")),
        "agent-doc-flow-io must stay a first-class workspace crate"
    );

    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    assert!(
        !orchestration_lib.contains("pub mod flow;")
            && !orchestration_lib.contains("mod flow;")
            && !orchestration_lib.contains("pub fn closeout_effects()")
            && !orchestration_lib.contains(
                "impl agent_doc_flow_io::closeout::CloseoutEffects for OrchestrationCloseoutEffects"
            ),
        "orchestration must delete the flow source module and runtime CloseoutEffects port"
    );
    let closeout_runtime =
        fs::read_to_string(manifest_dir.join("agent-doc-closeout-runtime-io/src/lib.rs")).unwrap();
    assert!(
        closeout_runtime.contains("pub fn closeout_effects()")
            && closeout_runtime.contains(
                "impl agent_doc_flow_io::closeout::CloseoutEffects for RuntimeCloseoutEffects"
            )
            && closeout_runtime.contains("pub static REPAIR_IO_EFFECTS"),
        "agent-doc-closeout-runtime-io should own closeout and repair runtime effects ports"
    );

    assert!(
        !manifest_dir
            .join("agent-doc-orchestration/src/flow")
            .exists(),
        "orchestration must not keep a test-only flow source module"
    );

    let closeout_tests =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/tests/flow_closeout.rs"))
            .unwrap();
    assert!(
        !closeout_tests.contains("crate::")
            && closeout_tests.contains("agent_doc_flow_io::closeout::")
            && closeout_tests.contains("agent_doc_closeout_runtime_io::closeout_effects()"),
        "moved closeout boundary tests should call flow-io directly through the focused closeout runtime effects port"
    );

    let flow_events =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/tests/flow_events.rs"))
            .unwrap();
    assert!(
        flow_events.contains("agent_doc_flow::types")
            && !flow_events.contains("agent_doc_orchestration::flow"),
        "flow event coverage should live as an integration test without an orchestration flow module"
    );

    for production_source in [
        "src/main.rs",
        "src/session_actor_cmd.rs",
        "agent-doc-orchestration/src/lib.rs",
        "agent-doc-orchestration/src/repair.rs",
        "agent-doc-orchestration/src/route.rs",
        "agent-doc-orchestration/src/write.rs",
    ] {
        let source = fs::read_to_string(manifest_dir.join(production_source)).unwrap();
        assert!(
            !source.contains("crate::flow::")
                && !source.contains("agent_doc_orchestration::flow::"),
            "{production_source} must call agent-doc-flow-io directly with the root closeout effects port instead of the orchestration flow facade"
        );
    }
}

#[test]
fn test_document_realtime_io_owns_pipeline_frontmatter_runtime_effects() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    for forbidden in [
        "PIPELINE_FRONTMATTER_EFFECTS",
        "PipelineFrontmatterEffects",
        "RUNTIME_PIPELINE_FRONTMATTER_EFFECTS as PIPELINE_FRONTMATTER_EFFECTS",
    ] {
        assert!(
            !orchestration_lib.contains(forbidden),
            "orchestration root must not re-export pipeline-frontmatter runtime effects: {forbidden}"
        );
    }

    let document_realtime_io =
        fs::read_to_string(manifest_dir.join("agent-doc-document-realtime-io/src/lib.rs")).unwrap();
    for required in [
        "pub struct RuntimePipelineFrontmatterEffects",
        "pub static RUNTIME_PIPELINE_FRONTMATTER_EFFECTS",
        "impl agent_doc_cycle_state_io::pipeline_frontmatter::PipelineFrontmatterEffects",
    ] {
        assert!(
            document_realtime_io.contains(required),
            "document realtime IO must own pipeline-frontmatter runtime effects: {required}"
        );
    }

    fn collect_rs_files(dir: &Path, files: &mut Vec<PathBuf>) {
        for entry in fs::read_dir(dir).unwrap() {
            let path = entry.unwrap().path();
            if path.is_dir() {
                collect_rs_files(&path, files);
            } else if path.extension().and_then(|extension| extension.to_str()) == Some("rs") {
                files.push(path);
            }
        }
    }

    let mut orchestration_files = Vec::new();
    collect_rs_files(
        &manifest_dir.join("agent-doc-orchestration/src"),
        &mut orchestration_files,
    );
    collect_rs_files(
        &manifest_dir.join("agent-doc-orchestration/tests"),
        &mut orchestration_files,
    );
    let mut saw_focused_runtime_effects = false;
    for path in orchestration_files {
        let source = fs::read_to_string(&path).unwrap();
        assert!(
            !source.contains("agent_doc_orchestration::PIPELINE_FRONTMATTER_EFFECTS")
                && !source.contains("crate::PIPELINE_FRONTMATTER_EFFECTS"),
            "{} must use document realtime IO directly instead of the orchestration pipeline-frontmatter facade",
            path.display()
        );
        saw_focused_runtime_effects |=
            source.contains("agent_doc_document_realtime_io::RUNTIME_PIPELINE_FRONTMATTER_EFFECTS");
    }
    assert!(
        saw_focused_runtime_effects,
        "orchestration call sites that need pipeline-frontmatter runtime effects should import document realtime IO directly"
    );
}

