fn test_agent_doc_frontmatter_owns_cross_document_security_review_policy() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let workspace_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    let workspace: toml::Value = toml::from_str(&workspace_manifest).unwrap();
    let members = workspace["workspace"]["members"].as_array().unwrap();
    assert!(
        members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-frontmatter-io")),
        "agent-doc-frontmatter-io must stay a first-class workspace crate for frontmatter file/path adapters"
    );

    let frontmatter_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-frontmatter/src/lib.rs")).unwrap();
    let security_review =
        fs::read_to_string(manifest_dir.join("agent-doc-frontmatter/src/security_review.rs"))
            .unwrap();

    assert!(
        frontmatter_lib.contains("pub mod security_review;"),
        "agent-doc-frontmatter should expose focused security-review policy"
    );
    for required in [
        "pub enum SecurityReviewSubject",
        "pub struct CrossDocumentSecurityReviewDecision",
        "pub fn cross_document_security_review_decision(",
        "CollaborationMode::Shared",
        "has_security_review()",
    ] {
        assert!(
            security_review.contains(required),
            "agent-doc-frontmatter must own cross-document security-review policy: {required}"
        );
    }

    let frontmatter_io_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-frontmatter-io/src/lib.rs")).unwrap();
    let frontmatter_io_security =
        fs::read_to_string(manifest_dir.join("agent-doc-frontmatter-io/src/security_review.rs"))
            .unwrap();
    assert!(
        frontmatter_io_lib.contains("pub mod security_review;"),
        "agent-doc-frontmatter-io should expose the focused security-review file/path adapter"
    );
    for required in [
        "pub fn enforce_cross_document_review(",
        "agent_doc_frontmatter::security_review::{",
        "cross_document_security_review_decision",
        "SecurityReviewSubject",
        "agent_doc_fs::same_document_path",
    ] {
        assert!(
            frontmatter_io_security.contains(required),
            "agent-doc-frontmatter-io must own the effectful cross-document security-review wrapper: {required}"
        );
    }
    for forbidden in [
        "CollaborationMode::Shared",
        "has_security_review()",
        "pub fn cross_document_security_review_decision(",
        "pub enum SecurityReviewSubject",
        "pub struct CrossDocumentSecurityReviewDecision",
        "pub use agent_doc_frontmatter::security_review",
        "pub(crate) use agent_doc_frontmatter::security_review",
    ] {
        assert!(
            !frontmatter_io_security.contains(forbidden),
            "agent-doc-frontmatter-io security review must adapt paths/errors, not re-own or facade frontmatter security-review policy: {forbidden}"
        );
    }

    let orchestration_security_path = manifest_dir.join("agent-doc-orchestration/src/security.rs");
    assert!(
        !orchestration_security_path.exists(),
        "orchestration must not keep security.rs as a frontmatter security-review adapter or facade"
    );
    let orchestration_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/lib.rs")).unwrap();
    assert!(
        !orchestration_lib.contains("pub mod security"),
        "orchestration must not expose security as a module facade"
    );
    for relative in ["src/extract.rs", "agent-doc-preflight-io/src/lib.rs"] {
        let source = fs::read_to_string(manifest_dir.join(relative)).unwrap();
        assert!(
            source.contains(
                "agent_doc_frontmatter_io::security_review::enforce_cross_document_review"
            ),
            "{relative} should call the focused frontmatter-io security-review wrapper directly"
        );
        for forbidden in [
            "agent_doc_orchestration::security",
            "crate::security::enforce_cross_document_review",
            "security::enforce_cross_document_review",
        ] {
            assert!(
                !source.contains(forbidden),
                "{relative} must not route cross-document security review through orchestration security: {forbidden}"
            );
        }
    }

    let frontmatter_io_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-frontmatter-io/Cargo.toml")).unwrap();
    let parsed: toml::Value = toml::from_str(&frontmatter_io_manifest).unwrap();
    let dependencies = parsed["dependencies"].as_table().unwrap();
    for required in ["agent-doc-frontmatter", "agent-doc-fs", "anyhow"] {
        assert!(
            dependencies.contains_key(required),
            "agent-doc-frontmatter-io should depend on {required} for cross-document security review adapters"
        );
    }
    for forbidden in [
        "agent-doc-core",
        "agent-doc-orchestration",
        "git2",
        "interprocess",
        "notify",
        "rusqlite",
        "tmux-router",
    ] {
        assert!(
            !dependencies.contains_key(forbidden),
            "agent-doc-frontmatter-io security-review adapter must stay free of core, orchestration, git, editor IPC, sqlite, or tmux crates"
        );
    }

    let frontmatter_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-frontmatter/Cargo.toml")).unwrap();
    let parsed: toml::Value = toml::from_str(&frontmatter_manifest).unwrap();
    let dependencies = parsed["dependencies"].as_table().unwrap();
    for forbidden in [
        "agent-doc-core",
        "agent-doc-orchestration",
        "git2",
        "interprocess",
        "notify",
        "rusqlite",
        "tmux-router",
    ] {
        assert!(
            !dependencies.contains_key(forbidden),
            "agent-doc-frontmatter security-review policy must stay free of core, orchestration, git, editor IPC, sqlite, or tmux crates"
        );
    }
}

#[test]
fn test_agent_doc_frontmatter_owns_lint_mode_policy() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let frontmatter_lib =
        fs::read_to_string(manifest_dir.join("agent-doc-frontmatter/src/lib.rs")).unwrap();
    let lint_policy =
        fs::read_to_string(manifest_dir.join("agent-doc-frontmatter/src/lint.rs")).unwrap();

    assert!(
        frontmatter_lib.contains("pub mod lint;"),
        "agent-doc-frontmatter should expose focused lint mode policy"
    );
    for required in [
        "pub enum LintCliMode",
        "pub enum LintModeSource",
        "pub const fn dialect_label",
        "pub fn resolve_lint_mode(",
        "\"strict\" | \"error\"",
        "LintModeSource::ProjectConfig",
    ] {
        assert!(
            lint_policy.contains(required),
            "agent-doc-frontmatter must own lint mode policy: {required}"
        );
    }

    let frontmatter_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-frontmatter/Cargo.toml")).unwrap();
    let parsed: toml::Value = toml::from_str(&frontmatter_manifest).unwrap();
    let dependencies = parsed["dependencies"].as_table().unwrap();
    for forbidden in [
        "agent-doc-core",
        "agent-doc-orchestration",
        "git2",
        "interprocess",
        "notify",
        "rusqlite",
        "tmux-router",
    ] {
        assert!(
            !dependencies.contains_key(forbidden),
            "agent-doc-frontmatter lint mode policy must stay free of core, orchestration, git, editor IPC, sqlite, or tmux crates"
        );
    }

    let root_manifest = fs::read_to_string(manifest_dir.join("Cargo.toml")).unwrap();
    let root: toml::Value = toml::from_str(&root_manifest).unwrap();
    let workspace_members = root["workspace"]["members"].as_array().unwrap();
    assert!(
        workspace_members
            .iter()
            .any(|member| member.as_str() == Some("agent-doc-lint-io")),
        "agent-doc-lint-io must be a workspace member"
    );
    let root_dependencies = root["dependencies"].as_table().unwrap();
    assert!(
        root_dependencies.contains_key("agent-doc-lint-io"),
        "root crate should depend on focused lint IO crate directly"
    );

    let lint_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-lint-io/Cargo.toml")).unwrap();
    let lint_manifest: toml::Value = toml::from_str(&lint_manifest).unwrap();
    let lint_dependencies = lint_manifest["dependencies"].as_table().unwrap();
    for required in [
        "agent-doc-frontmatter",
        "agent-doc-project-config-io",
        "anyhow",
        "tagpath",
    ] {
        assert!(
            lint_dependencies.contains_key(required),
            "agent-doc-lint-io should depend on lint gate dependency: {required}"
        );
    }
    for forbidden in [
        "agent-doc-orchestration",
        "agent-doc-git-io",
        "agent-doc-sqlite",
        "agent-doc-tmux-io",
        "interprocess",
    ] {
        assert!(
            !lint_dependencies.contains_key(forbidden),
            "agent-doc-lint-io must stay a lint adapter, not orchestration/app state: {forbidden}"
        );
    }

    let lint_gate = fs::read_to_string(manifest_dir.join("agent-doc-lint-io/src/lib.rs")).unwrap();
    for forbidden in [
        "pub enum LintCliMode",
        "pub enum LintModeSource",
        "fn dialect_label(",
        "pub fn resolve_lint_mode(",
        "pub use agent_doc_frontmatter::lint",
        "pub(crate) use agent_doc_frontmatter::lint",
    ] {
        assert!(
            !lint_gate.contains(forbidden),
            "lint_gate must adapt IO/tagpath only, not re-own or facade frontmatter lint policy: {forbidden}"
        );
    }
    assert!(
        lint_gate.contains("lint::{LintCliMode, LintModeSource, dialect_label, resolve_lint_mode}")
            && lint_gate
                .contains("resolve_mode_from_project_dialect(content, cli, project.lint.dialect)")
            && lint_gate.contains("resolve_lint_mode(content, cli, project_dialect)")
            && lint_gate.contains("tagpath::lint::agent_doc")
            && lint_gate.contains("pub type OpsLogger")
            && lint_gate.contains("pub fn run_with_logger"),
        "agent-doc-lint-io should call focused frontmatter lint policy and own tagpath gate IO"
    );

    let orchestration_manifest =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/Cargo.toml")).unwrap();
    let orchestration: toml::Value = toml::from_str(&orchestration_manifest).unwrap();
    let orchestration_dependencies = orchestration["dependencies"].as_table().unwrap();
    assert!(
        orchestration_dependencies.contains_key("agent-doc-lint-io"),
        "agent-doc-orchestration should depend on the focused lint IO crate"
    );
    assert!(
        !orchestration_dependencies.contains_key("tagpath"),
        "tagpath should be confined to agent-doc-lint-io after lint gate extraction"
    );

    assert!(
        !manifest_dir
            .join("agent-doc-orchestration/src/lint_gate.rs")
            .exists(),
        "orchestration must not keep a lint_gate facade module"
    );
    let orchestration_write =
        fs::read_to_string(manifest_dir.join("agent-doc-orchestration/src/write.rs")).unwrap();
    let orchestration_stream =
        fs::read_to_string(manifest_dir.join("agent-doc-stream-io/src/lib.rs")).unwrap();
    assert!(
        orchestration_write.contains("agent_doc_lint_io::run_with_logger")
            && orchestration_write.contains("agent_doc_ops_log_io::log_op")
            && orchestration_stream.contains("agent_doc_lint_io::run_with_logger")
            && orchestration_stream.contains("agent_doc_ops_log_io::log_op"),
        "orchestration write/stream should inject ops-log into focused lint IO directly"
    );
    for forbidden in [
        "tagpath::",
        "lint_agent_doc",
        "format_findings_text",
        "AgentDocOptions",
        "LintFinding",
        "resolve_mode_from_project_dialect",
    ] {
        assert!(
            !orchestration_write.contains(forbidden) && !orchestration_stream.contains(forbidden),
            "orchestration write/stream must not re-own tagpath lint adapter after extraction: {forbidden}"
        );
    }

    for relative_path in [
        "src/main.rs",
        "agent-doc-write-command-io/src/lib.rs",
        "agent-doc-stream-io/src/lib.rs",
    ] {
        let source = fs::read_to_string(manifest_dir.join(relative_path)).unwrap();
        assert!(
            source.contains("agent_doc_frontmatter::lint::LintCliMode")
                && !source.contains("lint_gate::LintCliMode"),
            "{relative_path} should use the frontmatter-owned LintCliMode directly"
        );
    }
}

